(()=>{const out={},ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('width','200');svg.setAttribute('height','100');svg.setAttribute('viewBox','0 0 100 50');const r=document.createElementNS(ns,'rect');r.setAttribute('width','10');r.setAttribute('height','20');svg.append(r);document.body.append(svg);const read=()=>{const m=r.getCTM(),screen=r.getScreenCTM(),own=svg.getCTM();return [svg.currentScale,svg.currentTranslate.x,svg.currentTranslate.y,[m.a,m.b,m.c,m.d,m.e,m.f],[screen.a,screen.b,screen.c,screen.d,screen.e,screen.f],[own.a,own.b,own.c,own.d,own.e,own.f]]};out.initial=read();svg.currentScale=3;svg.currentTranslate.x=4;svg.currentTranslate.y=5;out.zoom=read();svg.currentScale=0;out.zero=read();svg.currentScale=-2;out.negative=read();svg.remove();out.detached=read();return out})()
